from random import sample

def simple_sort(nums):
    for i in range(len(nums)-1):
        for j in range(i+1, len(nums)):
            if nums[i] > nums[j]:
                nums[i], nums[j] = nums[j], nums[i]
    return nums

nums = sample(range(1, 20), 10)
print(f"원본 리스트: {nums}")
simple_sort(nums)
print("내림차순 정렬된 리스트:", nums)
